  shape(alm, { fill: glow ? '#E9FBFF' : SM.eyeW, stroke: SM.ink, lw, smooth: .8 });
  const lx = clamp(o.lookX || 0, -1, 1), ly = clamp(o.lookY || 0, -1, 1), ir = kind === 'wide' ? .3 : .36;
  const ix = cx + lx * .34 * narrow, iy = cy + ly * .18;
