    const sd = i ? 1 : -1;
    let up = kind === 'up' ? .4 : kind === 'focused' ? -.18 : 0, inner = kind === 'worried' ? -.4 : kind === 'angry' ? .38 : 0;
    if (kind === 'quizzical') { up = i ? .55 : -.05; inner = i ? -.1 : .15; }
