  X.save(); X.translate(A.handL[0], A.handL[1]); X.scale(ps, ps);
  jeHand([0, 0], -.15, -1, 'grip', .1); X.restore();
  X.save(); X.translate(A.handR[0], A.handR[1]); X.scale(ps, ps);
  line([[-.65, .65], [1.05, -1.05]], { stroke: JE.ink, lw: .25 });
